    M = int(next(it))
    edges = []
    for _ in range(M):
        s = int(next(it)) - 1
        t = int(next(it)) - 1
        edges.append((s, t))

    def solve_without(exclude_idx):
        adj = [[] for _ in range(N)]
        for i, (s, t) in enumerate(edges):
            if i == exclude_idx:
                continue
            adj[s].append(t)
        INF = 10**9
        dist = [INF] * N
        dist[0] = 0
        for _ in range(N - 1):
            updated = False
            for u in range(N):
                if dist[u] == INF:
                    continue
                for v in adj[u]:
                    if dist[v] > dist[u] + 1:
                        dist[v] = dist[u] + 1
                        updated = True
            if not updated:
                break
        if dist[N - 1] == INF:
            return -1
        return dist[N - 1]

    results = [solve_without(i) for i in range(M)]
    print('\n'.join(map(str, results)))

if __name__ == '__main__':
    main()
